    KD.mode = 'ubah'; KD.reg = r; KD.items = (r.items || []).map(it => baris({ kode: it.kode, uraian: it.uraian, vol: String(N(it.vol)), sat: it.sat, harga: String(N(it.harga)), wbs: it.wbs, noPermintaan: it.noPermintaan })).concat([baris()]);
